using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

public class FishLineThin
{
    public static void Run()
    {
        StringBuilder sb = new StringBuilder();

        UnityEngine.Object config = AssetDatabase.LoadAssetAtPath<UnityEngine.Object>("Assets/Data/Config/HookConfig.asset");
        SerializedObject serialized = new SerializedObject(config);
        SerializedProperty width = serialized.FindProperty("LineWidthMeters");

        width.floatValue = 0.02f;
        serialized.ApplyModifiedPropertiesWithoutUndo();
        EditorUtility.SetDirty(config);
        sb.AppendLine("HookConfig.LineWidthMeters = " + width.floatValue);

        Material line = AssetDatabase.LoadAssetAtPath<Material>("Assets/Art/Materials/Mat_Tackle_Line.mat");

        if (line != null)
        {
            line.SetColor("_BaseColor", new Color(0.13f, 0.15f, 0.18f, 1f));
            EditorUtility.SetDirty(line);
            sb.AppendLine("Mat_Tackle_Line color = " + line.GetColor("_BaseColor"));
        }

        AssetDatabase.SaveAssets();

        Scene scene = default;

        for (int i = 0; i < SceneManager.sceneCount; i++)
        {
            Scene candidate = SceneManager.GetSceneAt(i);

            if (candidate.name == "Fishing" && candidate.isLoaded)
                scene = candidate;
        }

        if (!scene.IsValid())
        {
            sb.AppendLine("SKIP  Fishing scene not open");
            Debug.Log("[FishLineThin]\n" + sb);
            return;
        }

        GameObject hook = GameObject.Find("World/Hook");
        LineRenderer renderer = hook != null ? hook.GetComponent<LineRenderer>() : null;
        GameObject rodAnchor = GameObject.Find("World/Rod/LineAnchor");

        renderer.widthCurve = new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(1f, 1f));
        renderer.widthMultiplier = 0.02f;
        renderer.numCapVertices = 0;
        renderer.numCornerVertices = 0;
        renderer.positionCount = 2;

        if (rodAnchor != null)
        {
            renderer.SetPosition(0, rodAnchor.transform.position);
            renderer.SetPosition(1, hook.transform.position);
        }

        EditorUtility.SetDirty(renderer);
        Bounds bounds = renderer.bounds;
        sb.AppendLine("scene line size(" + bounds.size.x.ToString("0.000") + "," + bounds.size.y.ToString("0.000") + "," + bounds.size.z.ToString("0.000") + ")");

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        sb.AppendLine("scene saved");

        Debug.Log("[FishLineThin]\n" + sb);
    }
}
